begin;
create extension if not exists pgtap with schema extensions;
set search_path = public,extensions;
select no_plan();
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','owner@example.test'),('22222222-2222-4222-8222-222222222222','stranger@example.test');
insert into profiles(user_id,data) values('11111111-1111-4111-8111-111111111111','{"name":"Owner"}');
insert into conversations(id,user_id,title) values('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','Private chat');
insert into messages(id,user_id,conversation_id,role,content) values('44444444-4444-4444-8444-444444444444','11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','user','I prefer remote roles');
insert into memories(user_id,key,content,source_message_id) values('11111111-1111-4111-8111-111111111111','preferences.location','Prefers remote roles','44444444-4444-4444-8444-444444444444');
insert into documents(id,user_id,name,path,mime_type,size,kind) values('55555555-5555-4555-8555-555555555555','11111111-1111-4111-8111-111111111111','Resume.pdf','11111111-1111-4111-8111-111111111111/resume.pdf','application/pdf',20,'resume');
insert into opportunities(id,user_id,input,company,role,recipient_email) values('66666666-6666-4666-8666-666666666666','11111111-1111-4111-8111-111111111111','Referral','Example Co','Engineer','referrer@example.test');
insert into research_sources(user_id,opportunity_id,url,title,content) values('11111111-1111-4111-8111-111111111111','66666666-6666-4666-8666-666666666666','https://example.com/careers','Careers','Public information');
insert into drafts(id,user_id,opportunity_id,recipient_email,subject,body) values('77777777-7777-4777-8777-777777777777','11111111-1111-4111-8111-111111111111','66666666-6666-4666-8666-666666666666','referrer@example.test','Referral request','Hello');
select is((select cardinality(cc_emails) from drafts limit 1),0,'Legacy inserts default to empty Cc');
select is((select cardinality(bcc_emails) from drafts limit 1),0,'Legacy inserts default to empty Bcc');
update drafts set cc_emails=array['team@example.test'],bcc_emails=array['archive@example.test'];
select is((select cc_emails[1] from drafts limit 1),'team@example.test','Cc recipients persist');
select is((select bcc_emails[1] from drafts limit 1),'archive@example.test','Bcc recipients persist');
select throws_ok($$update drafts set cc_emails=array_fill('a@example.test'::text,array[51])$$,'23514',null,'Recipient count is bounded');
insert into mcp_configs(user_id,name,url) values('11111111-1111-4111-8111-111111111111','Trusted server','https://example.com/mcp');
insert into integration_credentials(user_id,kind,reference,encrypted_payload) values('11111111-1111-4111-8111-111111111111','gmail','primary','encrypted');
insert into storage.objects(bucket_id,name,owner_id) values('documents','11111111-1111-4111-8111-111111111111/resume.pdf','11111111-1111-4111-8111-111111111111');

select ok((select bool_and(relrowsecurity) from pg_class where oid in ('profiles'::regclass,'memories'::regclass,'drafts'::regclass,'integration_credentials'::regclass)),'RLS enabled on account and secret tables');
select ok(not has_table_privilege('authenticated','integration_credentials','select'),'Authenticated clients cannot read credentials');
select ok(not has_function_privilege('authenticated','claim_send(uuid,uuid,integer,uuid,jsonb)','execute'),'Clients cannot claim delivery');
select ok(not has_function_privilege('anon','finish_send(uuid,uuid,text,text,text)','execute'),'Anonymous clients cannot finalize delivery');
set local role anon;
select throws_ok('select * from profiles','42501',null,'Anonymous profile access denied');
select throws_ok('select * from drafts','42501',null,'Anonymous draft access denied');
select throws_ok('select * from integration_credentials','42501',null,'Anonymous secret access denied');
select is((select count(*)::int from storage.objects where bucket_id='documents'),0,'Anonymous storage reads denied');
reset role;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from profiles),0,'Unrelated user cannot read profile');
select is((select count(*)::int from memories),0,'Unrelated user cannot read memories');
select is((select count(*)::int from conversations),0,'Unrelated user cannot read conversations');
select is((select count(*)::int from messages),0,'Unrelated user cannot read messages');
select is((select count(*)::int from documents),0,'Unrelated user cannot read documents');
select is((select count(*)::int from opportunities),0,'Unrelated user cannot read opportunities');
select is((select count(*)::int from research_sources),0,'Unrelated user cannot read research');
select is((select count(*)::int from drafts),0,'Unrelated user cannot read drafts');
select is((select count(*)::int from mcp_configs),0,'Unrelated user cannot read MCP configuration');
select is((select count(*)::int from storage.objects where bucket_id='documents'),0,'Unrelated user cannot read stored resume');
select throws_ok('update profiles set data=''{}''','42501',null,'Direct client updates are denied');
select throws_ok('delete from memories','42501',null,'Direct client deletes are denied');
select throws_ok('insert into profiles(user_id) values(''22222222-2222-4222-8222-222222222222'')','42501',null,'Direct client inserts are denied');
reset role;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from profiles),1,'Owner reads their profile');
select is((select count(*)::int from memories),1,'Owner reads their memories');
select is((select count(*)::int from messages),1,'Owner reads their messages');
select is((select count(*)::int from drafts),1,'Owner reads their draft');
select is((select count(*)::int from storage.objects where bucket_id='documents'),1,'Owner reads their stored resume');
select throws_ok('select * from integration_credentials','42501',null,'Even owner cannot read integration secrets directly');
reset role;

select throws_ok($$insert into messages(user_id,conversation_id,role,content) values('22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333','user','Cross-account')$$,'23503',null,'Composite foreign keys prevent cross-account relationships');
select throws_ok($$select claim_send('22222222-2222-4222-8222-222222222222','77777777-7777-4777-8777-777777777777',1,'88888888-8888-4888-8888-888888888888','{}')$$,'P0001','Draft changed or has already been sent','Cannot claim another owner draft');
select throws_ok($$select claim_send('11111111-1111-4111-8111-111111111111','77777777-7777-4777-8777-777777777777',9,'88888888-8888-4888-8888-888888888888','{}')$$,'P0001','Draft changed or has already been sent','Stale draft version cannot be sent');
select lives_ok($$select claim_send('11111111-1111-4111-8111-111111111111','77777777-7777-4777-8777-777777777777',1,'88888888-8888-4888-8888-888888888888','{"subject":"Referral request","body":"Hello","cc_emails":["team@example.test"],"bcc_emails":["archive@example.test"]}')$$,'Saved draft can be claimed');
select is((select status from drafts where id='77777777-7777-4777-8777-777777777777'),'sending','Claim locks the draft');
select throws_ok($$select claim_send('11111111-1111-4111-8111-111111111111','77777777-7777-4777-8777-777777777777',1,'99999999-9999-4999-8999-999999999999','{}')$$,'P0001','Draft changed or has already been sent','Second click cannot claim the same draft');
select throws_ok($$select claim_send('11111111-1111-4111-8111-111111111111','77777777-7777-4777-8777-777777777777',1,'88888888-8888-4888-8888-888888888888','{}')$$,'P0001','This send request has already been processed','Duplicate idempotency key is rejected');
select lives_ok($$select finish_send('11111111-1111-4111-8111-111111111111',(select id from send_attempts limit 1),'unknown',null,'Timeout')$$,'Uncertain delivery is persisted');
select is((select status from drafts where id='77777777-7777-4777-8777-777777777777'),'unknown','Uncertain drafts remain locked');
select throws_ok($$select claim_send('11111111-1111-4111-8111-111111111111','77777777-7777-4777-8777-777777777777',1,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','{}')$$,'P0001','Draft changed or has already been sent','Unknown delivery cannot be automatically retried');
select is((select snapshot->>'body' from send_attempts limit 1),'Hello','Delivery snapshot preserves reviewed text');
select is((select snapshot->'bcc_emails'->>0 from send_attempts limit 1),'archive@example.test','Send snapshot preserves Bcc');
select lives_ok($$select set_default_document('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555')$$,'Owner can choose default resume');
select is((select count(*)::int from documents where is_default),1,'Exactly one default resume');
select is((select count(*)::int from relevant_memories('22222222-2222-4222-8222-222222222222','remote')),0,'Memory search cannot cross ownership');
select * from finish();
rollback;
